/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status that is not closed. `status=open` expands to this list. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/** Status tokens the filter vocabulary accepts in addition to concrete statuses. */
export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;

export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

export type IssueStatusToken = IssueStatus | IssueStatusGroup;

const ISSUE_STATUS_GROUP_MEMBERS: Readonly<
  Record<IssueStatusGroup, readonly IssueStatus[]>
> = {
  open: OPEN_ISSUE_STATUSES,
  closed: CLOSED_ISSUE_STATUSES,
};

export function isIssueStatus(value: string): value is IssueStatus {
  return (ISSUE_STATUSES as readonly string[]).includes(value);
}

export function isIssueStatusToken(value: string): value is IssueStatusToken {
  return (
    isIssueStatus(value) ||
    (ISSUE_STATUS_GROUPS as readonly string[]).includes(value)
  );
}

/** Expands `open` / `closed`, keeps concrete statuses, and drops duplicates. */
export function expandIssueStatusTokens(
  tokens: readonly IssueStatusToken[],
): readonly IssueStatus[] {
  const seen = new Set<IssueStatus>();
  const expanded: IssueStatus[] = [];

  const push = (status: IssueStatus): void => {
    if (seen.has(status)) return;
    seen.add(status);
    expanded.push(status);
  };

  for (const token of tokens) {
    if (token === "open" || token === "closed") {
      for (const status of ISSUE_STATUS_GROUP_MEMBERS[token]) push(status);
      continue;
    }
    push(token);
  }

  return expanded;
}

