const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real UTC calendar date (`YYYY-MM-DD`), and nothing else. */
export function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Exclusive upper bound for a calendar-date due filter: midnight UTC at the
 * start of the next day, so the chosen day itself is included.
 */
export function calendarDateExclusiveEnd(value: string): IsoTimestamp {
  const match = CALENDAR_DATE.exec(value);
  if (match === null || !isCalendarDate(value)) {
    throw new RangeError(`Malformed calendar date: "${value}"`);
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  return toIsoTimestamp(new Date(Date.UTC(year, month - 1, day + 1)));
