function encodeSegment(segment: string): string {
  // A nav segment may carry a query (`issues?assignee=me`). Encoding the `?`
  // would fold the filter into the path and the list would never see it.
  const queryAt = segment.indexOf("?");
  if (queryAt === -1) return encodeURIComponent(segment);
  return `${encodeURIComponent(segment.slice(0, queryAt))}${segment.slice(queryAt)}`;
}

