import type { LabelId, ProjectId, UserId } from "@/types/common";
import {
  expandIssueStatusTokens,
  isIssueStatusToken,
  ISSUE_PRIORITIES,
  type IssueFilter,
  type IssuePriority,
  type IssueStatusToken,
} from "@/types/issue";

export const UNASSIGNED_TOKEN = "none";
/** Resolved by the service against the signed-in user; the codec leaves it as-is. */
export const ME_TOKEN = "me";

