input.new_string:
import { z } from "zod";
import { isCalendarDate } from "@/lib/date";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import { ISSUE_STATUSES } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** Concrete statuses plus the `open` and `closed` groups. */
export const issueStatusFilterTokenSchema = z.enum([
  ...ISSUE_STATUSES,
  "open",
  "closed",
]);

function splitCommaList(value: string): string[] {
  return value
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/**
 * A status filter is either an array of tokens or the comma list the URL and
 * the ops export send (`open`, `todo,done`). Unknown tokens are refused.
 */
export const issueStatusFilterSchema = z.union([
  z.array(issueStatusFilterTokenSchema),
  z
    .string()
    .transform(splitCommaList)
    .pipe(z.array(issueStatusFilterTokenSchema)),
]);

/** A user id, the signed-in user, or — for assignees — nobody. */
export const assigneeFilterSchema = z.union([
  z.literal("me"),
  z.literal("none").transform(() => null),
  z.null(),
  userIdSchema,
]);

export const authorFilterSchema = z.union([z.literal("me"), userIdSchema]);

const calendarDateSchema = z
  .string()
  .regex(/^\d{4}-\d{2}-\d{2}$/)
  .refine(isCalendarDate, "must be a real calendar date");

/** `YYYY-MM-DD` (the whole UTC day) or a full ISO-8601 timestamp. */
export const dueBeforeSchema = z.union([
  isoTimestampSchema,
  calendarDateSchema,
]);

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: issueStatusFilterSchema.optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: assigneeFilterSchema.optional(),
    authorId: authorFilterSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: dueBeforeSchema.optional(),
    archivedOnly: z.boolean().optional(),
    /** Raw URL token. `1` mixes archived rows in; `only` lists nothing else. */
    archived: z.enum(["1", "only"]).optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape)
  .transform((value) => {
    const { archived, ...rest } = value;
    if (archived === "only") return { ...rest, archivedOnly: true };
    if (archived === "1") return { ...rest, includeArchived: true };
    return rest;
  });

