/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `null` and `undefined` both arrive from the "Anyone" option of the
    // filter bar, so neither narrows the list.
    input.assigneeId ? eq(issues.assigneeId, input.assigneeId) : undefined,
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    input.labelIds === undefined || input.labelIds.length === 0
      ? undefined
      : inArray(
          issues.id,
          getDb()
            .select({ id: issueLabels.issueId })
            .from(issueLabels)
            .where(
              and(
                orgPredicate(issueLabels.orgId, input.orgId),
                inArray(issueLabels.labelId, [...input.labelIds]),
              ),
            ),
        ),
  );
}

input.new_string:
/**
 * `undefined` does not filter. `null` and `"none"` are unassigned. `"me"` is
 * resolved by the service before it reaches here; a leftover sentinel matches
 * no row rather than every row.
 */
function assigneePredicate(
  assigneeId: IssueFilterInput["assigneeId"],
): SQL | undefined {
  if (assigneeId === undefined) return undefined;
  if (assigneeId === null || assigneeId === "none") return isNull(issues.assigneeId);
  return eq(issues.assigneeId, assigneeId);
}

/** Every listed label must be present. Any-of is what status and priority do. */
function labelPredicate(
  orgId: IssueFilterInput["orgId"],
  labelIds: IssueFilterInput["labelIds"],
): SQL | undefined {
  if (labelIds === undefined || labelIds.length === 0) return undefined;

  const unique = [...new Set(labelIds)];
  return and(
    ...unique.map((labelId) =>
      inArray(
        issues.id,
        getDb()
          .select({ id: issueLabels.issueId })
          .from(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, orgId),
              eq(issueLabels.labelId, labelId),
            ),
          ),
      ),
    ),
  );
}

/**
 * A calendar date includes that whole UTC day. A timestamp is strict: issues
 * due at that instant are left out. Rows with no due date never match.
 */
function dueBeforePredicate(bound: string): SQL {
  const upper = isCalendarDate(bound) ? calendarDateExclusiveEnd(bound) : bound;
  return lt(issues.dueAt, upper);
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const scope: ArchiveScope =
    input.archivedOnly === true
      ? { archivedOnly: true }
      : shouldFilterArchived(input)
        ? {}
        : { includeArchived: true };

  const statuses =
    input.status === undefined || input.status.length === 0
      ? []
      : expandIssueStatusTokens(input.status as readonly IssueStatusToken[]);

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, [...statuses]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    assigneePredicate(input.assigneeId),
    input.authorId === undefined || input.authorId === "me"
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined
      ? undefined
      : dueBeforePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    labelPredicate(input.orgId, input.labelIds),
  );
}

