export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

input.new_string:
/** `me` means the acting user for both the page and an API caller. */
function resolveActorFilter(actor: Actor, input: IssueFilterInput): IssueFilterInput {
  return {
    ...input,
    assigneeId: input.assigneeId === "me" ? actor.userId : input.assigneeId,
    authorId: input.authorId === "me" ? actor.userId : input.authorId,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(resolveActorFilter(actor, input));
}

