/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

input.new_string:
const STATUS_GROUPS: Readonly<Record<IssueStatusGroup, readonly IssueStatus[]>> = {
  open: OPEN_ISSUE_STATUSES,
  closed: CLOSED_ISSUE_STATUSES,
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

/** Adds or removes every member of `open` or `closed`. */
export function toggleStatusGroup(
  filter: IssueFilter,
  group: IssueStatusGroup,
): IssueFilter {
  const members = STATUS_GROUPS[group];
  const current = filter.status ?? [];
  const allOn = members.every((status) => current.includes(status));
  const next = allOn
    ? current.filter((status) => !members.includes(status))
    : [
        ...current,
        ...members.filter((status) => !current.includes(status)),
      ];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

function groupIsActive(filter: IssueFilter, group: IssueStatusGroup): boolean {
  const current = filter.status ?? [];
  return STATUS_GROUPS[group].every((status) => current.includes(status));
}

