}

function stripDueBefore(filter: IssueFilter): IssueFilter {
  const { dueBefore: _dueBefore, ...rest } = filter;
  return rest;
}

function withArchived(filter: IssueFilter, raw: string): IssueFilter {
  const { includeArchived: _includeArchived, archivedOnly: _archivedOnly, ...rest } =
