import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { exportIssuesSchema } from "@/schemas/export";
import { issueFilterSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "@/tests-fixtures";

const ORG = "01HZZZAAAAAAAAAAAAAAAAAAAA";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

function assert(cond: unknown, message: string): void {
  if (!cond) throw new Error(message);
}

const open = parseIssueFilterParams(params("status=open"));
assert(
  JSON.stringify(open.status) ===
    JSON.stringify(["backlog", "todo", "in_progress", "in_review"]),
  `open expand ${JSON.stringify(open.status)}`,
);
const closed = parseIssueFilterParams(params("status=closed,todo"));
assert(
  JSON.stringify(closed.status) === JSON.stringify(["done", "canceled", "todo"]),
  `closed expand ${JSON.stringify(closed.status)}`,
);
assert(parseIssueFilterParams(params("assignee=me")).assigneeId === "me", "me");
assert(parseIssueFilterParams(params("assignee=none")).assigneeId === null, "none");
assert(parseIssueFilterParams(params("author=me")).authorId === "me", "author me");
assert(
  parseIssueFilterParams(params("due_before=2026-03-15")).dueBefore === "2026-03-15",
  "date",
);
assert(parseIssueFilterParams(params("archived=only")).archivedOnly === true, "only");
assert(
  issueFilterToParams({ archivedOnly: true }).archived === "only",
  "serialize only",
);
assert(
  parseIssueFilterParams(params("status=todo,nonsense,done")).status?.join() ===
    "todo,done",
  "drop unknown",
);

const parsed = issueFilterSchema.parse({
  orgId: ORG,
  status: "open",
  assigneeId: "me",
  authorId: "me",
  dueBefore: "2026-03-15",
  archived: "only",
});
assert(JSON.stringify(parsed.status) === JSON.stringify(["open"]), `schema status ${parsed.status}`);
assert(parsed.assigneeId === "me", "schema me");
assert(parsed.authorId === "me", "schema author");
assert(parsed.dueBefore === "2026-03-15", "schema date");
assert(parsed.archivedOnly === true, "schema only");
assert(!("archived" in parsed), "archived stripped");

const none = issueFilterSchema.parse({ orgId: ORG, assigneeId: "none" });
assert(none.assigneeId === null, "schema none");

const stamp = issueFilterSchema.parse({
  orgId: ORG,
  dueBefore: "2026-03-15T12:00:00.000Z",
});
assert(stamp.dueBefore === "2026-03-15T12:00:00.000Z", "schema stamp");

assert(
  issueFilterSchema.safeParse({ orgId: ORG, status: "open,shipped" }).success === false,
  "refuse unknown",
);
assert(
  issueFilterSchema.safeParse({ orgId: ORG, dueBefore: "2026-02-31" }).success === false,
  "refuse bad date",
);
assert(
  exportIssuesSchema.safeParse({ orgId: ORG, status: "open" }).success === true,
  "export open",
);
assert(
  exportIssuesSchema.safeParse({ orgId: ORG, status: ["open", "done"] }).success === true,
  "export array",
);

const cleanup = await useTemporaryDatabase();
const tenant = await createTenant("filter-check");
const labelA = await labelRepo.insertLabel({
  orgId: tenant.org.id,
  name: "bug",
  color: "#ef4444",
  description: null,
});
const labelB = await labelRepo.insertLabel({
  orgId: tenant.org.id,
  name: "regression",
  color: "#22c55e",
  description: null,
});

async function add(overrides: Record<string, unknown>) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    {
      ...issueInput(tenant.org.id, tenant.project.id, {}),
      ...overrides,
    } as never,
    tenant.userIds.owner,
    number,
  );
}

const both = await add({
  title: "both labels",
  labelIds: [labelA.id, labelB.id],
  assigneeId: null,
  dueAt: "2026-03-15T15:00:00.000Z",
  status: "todo",
});
const one = await add({
  title: "one label",
  labelIds: [labelA.id],
  assigneeId: tenant.userIds.member,
  dueAt: "2026-03-15T08:00:00.000Z",
  status: "done",
});
const later = await add({
  title: "later",
  labelIds: [],
  assigneeId: tenant.userIds.member,
  dueAt: "2026-03-16T00:00:00.000Z",
  status: "todo",
});
const noDue = await add({
  title: "no due",
  labelIds: [labelA.id, labelB.id],
  assigneeId: null,
  dueAt: null,
  status: "backlog",
});
const archived = await add({
  title: "archived",
  labelIds: [],
  assigneeId: tenant.userIds.owner,
  status: "todo",
});
await issueRepo.archiveIssue(tenant.org.id, archived.id);

const base = { orgId: tenant.org.id, limit: 50, cursor: null };

const labels = await issueRepo.listIssues({
  ...base,
  labelIds: [labelA.id, labelB.id],
});
assert(
  labels.items.map((i) => i.id).sort().join() === [both.id, noDue.id].sort().join(),
  `labels all-of got ${labels.items.map((i) => i.title)} total ${labels.total}`,
);
assert(labels.total === labels.items.length, "label total");

const unassigned = await issueRepo.listIssues({ ...base, assigneeId: null });
assert(
  unassigned.items.every((i) => i.assigneeId === null),
  `unassigned ${unassigned.items.map((i) => i.title)}`,
);
assert(unassigned.items.some((i) => i.id === both.id), "includes unassigned");
assert(!unassigned.items.some((i) => i.id === one.id), "excludes assigned");

const byDate = await issueRepo.listIssues({ ...base, dueBefore: "2026-03-15" });
const dateIds = byDate.items.map((i) => i.id);
assert(dateIds.includes(both.id) && dateIds.includes(one.id), `date includes day ${byDate.items.map((i) => i.title)}`);
assert(!dateIds.includes(later.id), "date excludes next day");
assert(!dateIds.includes(noDue.id), "date excludes undated");
assert(byDate.total === byDate.items.length, "date total");

const byStamp = await issueRepo.listIssues({
  ...base,
  dueBefore: "2026-03-15T12:00:00.000Z",
});
const stampIds = byStamp.items.map((i) => i.id);
assert(stampIds.includes(one.id), "stamp includes morning");
assert(!stampIds.includes(both.id), "stamp excludes afternoon");

const only = await issueRepo.listIssues({ ...base, archivedOnly: true });
assert(only.items.map((i) => i.id).join() === archived.id, `only archived ${only.items.map((i) => i.title)}`);
assert(only.total === 1, "only total");

const live = await issueRepo.listIssues(base);
assert(!live.items.some((i) => i.id === archived.id), "live hides archived");

const openPage = await issueService.listIssues(tenant.actors.member, {
  ...base,
  status: ["open"],
  assigneeId: "me",
});
assert(
  openPage.items.every((i) => i.assigneeId === tenant.userIds.member),
  `me ${openPage.items.map((i) => `${i.title}:${i.assigneeId}`)}`,
);
assert(
  openPage.items.every((i) => i.status !== "done" && i.status !== "canceled"),
  "open group",
);
assert(openPage.items.some((i) => i.id === later.id), "member's open issue");
assert(!openPage.items.some((i) => i.id === one.id), "done excluded from open");

console.log("ok");
cleanup();

